class LmdbProviderClosePersistenceRegressionTest {
	private static final String QUERY = "SELECT ?s WHERE { ?s <urn:provider-fence:p> ?v FILTER(?v = 5) }";

	@Test
	void normalClosePersistsCurrentFilterAndOperatorEvidence(@TempDir(cleanup = CleanupMode.NEVER) Path evidence)
			throws Exception {
		Path directory = evidence.resolve("store");
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		repository.init();
		boolean shut = false;
		try {
			LmdbTestUtil.awaitPostReadyInitialization(store, 30, TimeUnit.SECONDS);
			LmdbEvaluationStatistics before = (LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics();
			long revision = before.estimatorRuntime().snapshotVersion();
			before.bindExecutionSnapshot(OptionalLong.of(revision));
			Filter filter = filter();
			before.recordFilterOutcome(filter, 20L, 80L);
			assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER,
					before.estimateFilterPass(filter).getSource(), "the filter evidence was published before the commit");

			LogicalLearningKey logical = LogicalLearningKey.of("filter", "condition", "children", "predicates",
					"v0", "none", "bag", "default");
			LearningApplicability applicability = new LearningApplicability(1L, 0L, "unconditional", revision,
					revision, 1L);
			PhysicalResidualKey physical = PhysicalResidualKey.of("filter", "statement-pattern", "spoc",
					"single", "none", "none", "none", "bound");
			RuntimeFeedbackContract.PredictionVector prediction = new RuntimeFeedbackContract.PredictionVector(
					1.0d, 1.0d, 1.0d, 1.0d, 0.0d, 1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
			RuntimeFeedbackContract contract = new RuntimeFeedbackContract(
					new LmdbRuntimeFeedbackDescriptor(null, null, logical, applicability, physical), prediction,
					prediction, 1.0d, 1.0d, 1.0d, Double.POSITIVE_INFINITY,
					RuntimeFeedbackContract.SemanticKind.ORDINARY, RuntimeFeedbackContract.Algorithm.STREAMING_CORRELATED,
					RuntimeFeedbackContract.Access.EXACT_LOOKUP, physical.hashCode(), revision, revision, 1L,
					RuntimeFeedbackContract.ADMIT_LOGICAL | RuntimeFeedbackContract.ADMIT_PHYSICAL);
			filter.setCostFeedbackTrackingEnabled(true);
			filter.setRuntimeFeedbackContract(contract);
			RuntimeFeedbackTarget target = before.resolveRuntimeFeedbackTarget(filter, contract);
			assertTrue(target.active());
			target.open();
			target.close(4L, 4.0d, 4L, 0L, 4L, 0L, 0L, 0L, 0L, 0L,
					EvaluationStatistics.TerminationClassification.EXHAUSTED);
			target.recordActualPhysicalImplementation(contract.physicalImplementationId());
			before.publishRuntimeFeedbackTargets(new RuntimeFeedbackTarget[] { target }, 1, true);
			LmdbOperatorFeedbackStats operator = before.estimatorRuntime().feedback();
			assertNotNull(operator.logicalPosterior(logical, applicability, FrontierCostDimension.OUTPUT_ROWS),
					"the typed operator evidence was published before the commit");

			repository.shutDown();
			shut = true;
			Path filters = directory.resolve("join-estimator.rjes.filters");
			Path operators = directory.resolve("join-estimator.rjes.operators");
			assertAll("normal shutdown writes both current learned providers",
					() -> assertTrue(Files.isRegularFile(filters), "filter sidecar exists"),
					() -> assertTrue(Files.isRegularFile(operators), "operator sidecar exists"));
			Files.copy(filters, evidence.resolve("original-filters-backup.bin"));
			Files.copy(operators, evidence.resolve("original-operators-backup.bin"));
			LmdbStore reopened = new LmdbStore(directory.toFile(), config());
			SailRepository second = new SailRepository(reopened);
			second.init();
			try {
				LmdbTestUtil.awaitPostReadyInitialization(reopened, 30, TimeUnit.SECONDS);
				LmdbEvaluationStatistics current = (LmdbEvaluationStatistics) reopened.getBackingStore()
						.getEvaluationStatistics();
				assertAll("the saved sidecars are usable after reopen",
						() -> assertEquals(EvaluationStatistics.FilterPassEstimate.Source.LEARNED_FILTER,
								current.estimateFilterPass(filter()).getSource()),
						() -> assertNotNull(current.estimatorRuntime().feedback().logicalPosterior(logical,
								applicability, FrontierCostDimension.OUTPUT_ROWS)));
			} finally {
				second.shutDown();
			}
		} finally {
			if (!shut) {
				repository.shutDown();
			}
		}
	}

	private static Filter filter() {
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, QUERY, null).getTupleExpr();
		PlanningGraphDomains.capture(root, PlanningGraphDomain.defaultGraph());
		Filter[] found = new Filter[1];
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				if (found[0] == null) {
					found[0] = filter;
				}
				super.meet(filter);
			}
		});
		return found[0];
	}

	private static LmdbStoreConfig config() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setSketchEstimatorEnabled(false)
				.setBackgroundRawSamplingEnabled(false).setDirectAdjacencyEnabled(false).setValueOverlayEnabled(false);
		config.setExperimentalQueryOptimizations(true);
		config.setFrontierEstimatorMode(FrontierEstimatorMode.SHADOW);
		return config;
	}

}
